// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testRegression_property() public {
        address dummy = address(0x1234);
        c.SetLogFile(dummy);
        c.Initialized();
        bool ok;
        try c.SetLogFile(address(0x5678)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
